insert into encontros (etapa_id, numero, tipo, titulo, tempo_liturgico, leitura_biblica, conteudo_html, preparo_html, ordem) select (select id from etapas where numero=3), 13, 'encontro', 'A vontade de Deus em nós', null, 'Lc 22,39-42', '<p><strong>Palavra inicial:</strong> prezados catequistas, no encontro de hoje, queremos refletir com os catequizandos sobre a vontade de Deus para nossa vida. Deus tem um projeto para a humanidade e para cada um de nós, que nem sempre condiz com o que queremos ou buscamos.</p> <p><strong>Preparar o ambiente:</strong> ambão com toalha da cor do Tempo Litúrgico, Bíblia, flores e vela.</p> <p><strong>Acolhida:</strong> o catequista acolhe os catequizandos saudando-os com a frase: “<em>Deus tem um projeto para você, N..., seja bem-vindo!</em>”.</p> <p><strong>Recordação da vida:</strong> quando todos estiverem na sala do encontro, ao redor da Mesa da Partilha ou da Mesa da Palavra, o catequista os convida a apresentar fatos e acontecimentos que marcaram a semana e a vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> o catequista inicia a oração de maneira bem espontânea, onde invoca o Espírito Santo, cantando ou rezando.</p> <p>O catequista convida a todos a cantar aclamando o Santo Evangelho. Em seguida, o catequizando dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> Lc 22,39-42.</p> <p>Depois de um momento de silêncio, o catequista lê o texto novamente, bem devagar, destacando alguns pontos.</p> <blockquote> <p><em>“...Pai, se queres, afasta de mim este cálice; contudo, não se faça a minha vontade mas a tua!”</em></p> </blockquote> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Reconstruir com os catequizandos o texto bíblico. Depois, pedir aos catequizandos para abrirem suas Bíblias na passagem proclamada na Mesa da Palavra e convidá-los a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar.</p> <p>Jesus reza ao Pai pedindo que se cumpra a sua vontade. Jesus, como verdadeiro homem, também teve a tentação de que, se possível, ele não precisasse beber do cálice, ou seja, passar pela morte. Mas a obediência de Cristo em cumprir até o último momento a vontade do Pai fez com que sua humanidade fosse glorificada e a morte vencida. Com sua obediência Jesus resgata o homem da morte eterna.</p> <p>Assim como Deus tinha um projeto para o Filho e este se cumpriu plenamente, Deus também tem um projeto para cada um de nós. Todo ser humano sonha e planeja o seu futuro, porém, com o passar do tempo, nem sempre as coisas acontecem como planejado, e quando isto acontece, muitos murmuram, falam mal e se revoltam contra Deus.</p> <p>Antes de planejarmos alguma coisa, como cristãos e seguidores do Mestre Jesus, temos que entregar nossa vida a Ele e consagrá-la totalmente a Deus. Devemos ter nossos planos e projetos, sim, mas tendo consciência de que é a vontade de Deus que deve prevalecer. Deus sabe o que é melhor para nós.</p> <p>Sendo assim, hoje somos convidados a fazer um projeto de vida pessoal. O que queremos para nossa vida e para o nosso futuro? Somos convidados hoje a já começar a pensar no que queremos. Mas claro, dentro deste projeto somos convidados a refletir o que se encaixa no projeto de salvação que Deus tem para nós. O que vai contra o que Deus pede e nos ensinou.</p> <p>Enfim, o catequista convida a todos a pensarem em seu projeto de vida, levando sempre em conta fazer a vontade de Deus, buscando como fim último o Reino de Deus. Deixando de lado os bens materiais e passageiros.</p> <p>O catequista poderá convidar os catequizandos a se colocarem em uma posição confortável e por alguns instantes de silêncio fazer um momento de oração e escuta.</p> <p><strong>Conclusão:</strong> Que possamos entregar nossa vida e nossas vontades a Deus, e com a ajuda do Espírito Santo, implorar a sua força para que possamos, em tudo, fazer a vontade de Deus.</p> <p><strong>Oração final:</strong> O catequista convida os catequizandos a ficarem em pé ao redor da Mesa da Palavra e a formularem orações e preces. Poderá rezar a oração do Pai-Nosso e concluir com a oração:</p> <blockquote> <p><em>Senhor Deus, que conheces a história de cada um de nós, envia o teu Espírito Santo, para que com o auxílio Dele consigamos buscar fazer a tua vontade em nossa vida e não a nossa. Por Cristo, nosso Senhor. Amém.</em></p> </blockquote> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte dizendo:</p> <blockquote> <p><em>“Em tudo fazei a vontade de Deus, N... Vai em paz e que o Senhor te acompanhe! Amém”.</em></p> </blockquote>', '<p>ambão com toalha da cor do Tempo Litúrgico, Bíblia, flores e vela.</p>', 16 where not exists (select 1 from encontros where etapa_id=(select id from etapas where numero=3) and ordem=16); -- A vontade de Deus em nós
insert into encontros (etapa_id, numero, tipo, titulo, tempo_liturgico, leitura_biblica, conteudo_html, preparo_html, ordem) select (select id from etapas where numero=3), 14, 'encontro', 'Assim na Terra como no Céu', null, 'Mt 7,21-23', '<p><strong>Palavra inicial:</strong> No encontro de hoje, queremos refletir com nossos catequizandos que Céu e Terra indicam a totalidade de toda a criação. Ao rezar “<em>seja feita a tua vontade, assim na Terra como no Céu</em>”, pedimos ao Pai que faça a sua vontade em todo lugar, em toda a criação.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, Bíblia, vela e flores.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os com a frase: “<em>Que a vontade de Deus se cumpra em todo lugar, N... Seja bem-vindo!</em>”.</p> <p><strong>Recordação da vida:</strong> Quando todos estiverem na sala de encontro, em clima de oração, ao redor da Mesa da Partilha ou da Mesa da Palavra, o catequista os motiva a recordar fatos e acontecimentos que marcaram a semana. O catequista poderá perguntar sobre o encontro anterior, pedindo que partilhem o que escreveram no <em>Diário</em> sobre o seu projeto de vida.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> o catequista conduz a oração inicial. Poderá invocar o Espírito Santo, rezando ou cantando.</p> <p>Um catequizando dirige-se até o ambão, de onde proclama o texto bíblico. Antes, porém, todos poderão cantar aclamando o santo Evangelho.</p> <p><strong>Leitura do texto bíblico:</strong> Mt 7,21-23.</p> <p>Depois de um momento de silêncio, o catequista lê o texto novamente, bem devagar, destacando alguns pontos.</p> <blockquote> <p><em>“Nem todo aquele que me diz: ‘Senhor! Senhor!’, entrará no reino dos Céus, mas quem fizer a vontade de meu Pai que está nos céus...”.</em></p> </blockquote> <p>Todos se dirigem para a mesa da partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Reconstruir com os catequizandos o texto bíblico. Deixar que falem. Depois, pedir aos catequizandos para abrirem suas Bíblias na passagem proclamada na Mesa da Palavra e convidá-los a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar.</p> <p>Após a reconstrução do texto bíblico, refletir com os catequizandos que na linguagem bíblica, quando se fala de “Céu e Terra”, o que se quer indicar é a totalidade do que existe, toda a criação. Mas como vimos na invocação inicial, “Céu” é o lugar próprio de Deus e “Terra” é o espaço do homem. Nessa perspectiva, pedimos que se realize entre a humanidade o que se dá em Deus. Que se realize na Terra o desígnio que decidiste no Céu; que se faça entre nós o que o Pai decidir.</p> <p>Orígenes, em um de seus comentários, escreveu: “Se fosse feita a vontade de Deus na Terra como se faz no Céu, a Terra já não seria Terra... seríamos então Céu”. Portanto, pedimos a Deus que a sua vontade se faça sempre e em todo lugar, que ninguém nem nada se feche aos seus desígnios, que sua vontade de salvação abrace a tudo.</p> <p>Jesus foi obediente até o fim, é caminho a seguir. Fazer a vontade do Pai nos introduz numa relação nova e especial com Ele. Jesus resume todos os mandamentos da lei no amor, que nos amemos uns aos outros. Pedimos que o amor que reina no Céu seja uma realidade na Terra. Onde reina o amor não há espaço para brigas, inveja, ciúmes, fofocas e violência.</p> <p>No Evangelho, Jesus diz que “<em>nem todo aquele que me diz: ‘Senhor! Senhor!’, entrará no Reino dos Céus mas só aquele que põe em prática a vontade de meu Pai que está nos céus</em>” (Mt 7,21). Ora, muitos de nós participamos da catequese, da santa Missa, mas quando chegamos em casa, desrespeitamos os pais, xingamos, mentimos e tantas outras coisas que não condizem com o que Deus quer de nós. É vontade de Deus que todos se salvem e sejam santos, que se amem mutuamente e tenham uma vida de serviço e de doação.</p> <p>O catequista poderá interrogar os catequizandos perguntando: como podemos fazer a vontade de Deus aqui na Terra, como no Céu? Como podemos fazer da Terra um pedacinho do Céu? O que é o Céu?</p> <p>Depois, convidá-los a um instante de oração, onde cada um poderá imaginar como a Terra seria diferente se fosse vivida como extensão do Céu, ou seja, se a vontade de Deus, que é amor, prevalecesse em todas as nossas escolhas e decisões. Neste momento de silêncio e oração, pedir para os catequizandos rezarem pela paz no mundo e pelo fim da intolerância religiosa.</p> <p><strong>Conclusão:</strong> Jesus foi o único obediente até o fim, o único que cumpriu plenamente a vontade do Pai. Deus sabe que somos fracos e pecadores, e por isso Cristo morreu por cada um de nós e nos deu a oportunidade de retornar ao paraíso, a viver junto de Deus. Como gesto concreto, no decorrer desta semana somos convidados a rezar por todas as pessoas que não tiveram a oportunidade de conhecer e fazer a experiência de Jesus Cristo. Somos convidados a rezar para que o Céu seja uma realidade já aqui na Terra, onde todos busquem fazer a vontade do Pai.</p> <p><strong>Oração final:</strong> O catequista convida os catequizandos a ficarem em pé ao redor da Mesa da Palavra e, de mãos dadas, em sinal de unidade, rezar a oração do Pai-Nosso e concluir com a oração:</p> <blockquote> <p><em>Senhor, Pai Santo, que resgataste toda a humanidade pela morte de Cruz de teu Filho, ajuda-nos a viver aqui na Terra a tua vontade, como no Céu, testemunhando e anunciando teu Reino de amor a todos os homens e mulheres. Por Cristo, nosso Senhor. Amém.</em></p> </blockquote> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <blockquote> <p><em>“Fazei a vontade de Deus, N... Vai em paz e que Ele te acompanhe! Amém”.</em></p> </blockquote> <h4>MATERIAL DE APOIO</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 2822 a 2827 do Catecismo da Igreja Católica (CIC).</p></li> </ul>', '<p>Ambão com toalha da cor do Tempo Litúrgico, Bíblia, vela e flores.</p>', 17 where not exists (select 1 from encontros where etapa_id=(select id from etapas where numero=3) and ordem=17); -- Assim na Terra como no Céu
insert into encontros (etapa_id, numero, tipo, titulo, tempo_liturgico, leitura_biblica, conteudo_html, preparo_html, ordem) select (select id from etapas where numero=3), 15, 'encontro', 'O pão nosso de cada dia nos dai hoje', null, 'Mt 6,25-34', '<p><strong>Palavra inicial:</strong> Neste encontro, desenvolveremos junto aos catequizandos que Jesus nos ensina a confiar na providência divina e também a sermos corresponsáveis por aqueles irmãos e irmãs que não possuem o pão em sua mesa.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, Bíblia, vela e recortes de revistas que mostram pássaros livres e um vaso de flor (preferencialmente lírio).</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os com a frase: “<em>Deus providencia o necessário para a nossa vida, N..., seja bem-vindo!</em>”, e os conduz para dentro da sala. Quando já estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas.</p> <p><strong>Recordação da vida:</strong> Ao redor da Mesa da Partilha ou da Mesa da Palavra, após serem acolhidos, farão uma retrospectiva da semana, e o catequista poderá perguntar sobre o encontro anterior, pedindo para que partilhem o que cada um experienciou. Poderão destacar, ainda, acontecimentos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista inicia a oração invocando o Espírito Santo, rezando ou cantando.</p> <p>O catequista convida a todos a cantarem, aclamando o Santo Evangelho. Em seguida, o catequizando dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura texto bíblico:</strong> Mt 6,25-34.</p> <p>Depois de um momento de silêncio, o catequista lê o texto novamente, bem devagar, destacando alguns pontos.</p> <blockquote> <p><em>“...não vos preocupeis com vossa vida, com o que comereis ou bebereis [...] Vosso Pai celeste sabe que necessitais de tudo isso. Buscai, pois, em primeiro lugar o reino de Deus e sua justiça e todas estas coisas vos serão dadas de acréscimo...”</em></p> </blockquote> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Reconstruir o texto bíblico com os catequizandos. Depois, pedir para abrirem suas Bíblias na passagem proclamada na Mesa da Palavra e convidá-los a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar.</p> <p>No texto, vemos a confiança que Jesus nos pede para depositar no Pai. Ele também confiava. Nos momentos de angústia e desespero pelos quais passou, a confiança que Ele depositava em Deus foi a força necessária para que seguisse em frente e não desanimasse. E nós? Nos nossos momentos de dificuldades, temos confiado na providência divina? Conhecemos alguém que mesmo diante de todo o sofrimento não se desesperou e esperou firme, tendo certeza do auxílio divino?</p> <p>Depois, conversar com os catequizandos sobre o quarto pedido do Pai-Nosso: “o pão nosso de cada dia nos dai hoje”.</p> <p>Com este pedido começa a segunda parte da Oração do Senhor. Nos três primeiros estava centrada em Deus: “teu nome”, “teu reino”, “tua vontade”. A partir de agora a atenção se volta para nós mesmos: “nosso pão”, “nossas ofensas”, “não nos deixes cair em tentação”, “livra-nos do mal”.</p> <p>Pedir pão é um gesto próprio dos mais pobres, que não têm o mínimo para viver. Na língua materna de Jesus, o pão significava “alimento” de modo geral, o mais básico e essencial para uma pessoa sobreviver. A vida depende do pão, e por isso pedimos a Deus o alimento necessário e indispensável para a nossa vida. Não vivemos sem nos alimentar, e pedindo o “pão” a Deus, reconhecemos nossa total dependência Dele. Ou seja, reconhecemos que dependemos de Deus inclusive para o nosso sustento material. Quando pedimos o pão ao Pai, estamos pedindo algo bom e necessário para viver.</p> <p>Porém, esse pedido não é feito no singular: “pão meu”, mas sim no plural, “pão nosso”, lembrando que o pão não é só minha necessidade particular, mas expressa a necessidade de todos os homens e mulheres da Terra. Pedimos ao Pai o pão de que cada ser humano necessita para viver. Não temos o direito de pensar apenas em nossa própria satisfação, nossas necessidades, e esquecer de milhões de pessoas que passam fome e não têm o mínimo para sobreviver. Quantos famintos e desnutridos estão espalhados pelo mundo ou mesmo ao nosso lado? Temos o dever e a obrigação, como cristãos, de partilhar o que temos. Enquanto houver alguém com necessidade e passando fome, o pão que guardamos e acumulamos é alimento injusto, não nos pertence. Lembremos o que disse Jesus no Evangelho de Mateus (25,35): “Tive fome e me destes de comer, tive sede e me destes de beber”. Portanto, ao fazer este pedido, não podemos ignorar os menos favorecidos. Sempre existe alguém mais pobre do que nós, com quem podemos partilhar o que temos em nossa mesa (seja alimento, roupas, brinquedos, livros etc.).</p> <p>Pedir o pão de cada dia significa pedir a Deus o necessário somente para o dia de HOJE, para o presente, sabendo que a cada dia temos necessidade dele, mas sem a preocupação de juntar bens para o futuro. Lembremos aqui o texto bíblico que hoje meditamos. Não pedimos riqueza nem bem-estar, mas o necessário para alimentar-nos dia a dia, cobrindo nossas necessidades fundamentais. Isto implica todo um estilo de vida sóbrio e confiante em Deus.</p> <p>Nos diz o CIC (2861), que o “pão nosso designa o alimento terrestre necessário à subsistência de todos nós e significa também o pão da vida: Palavra de Deus e corpo de Cristo”. Ao pedir ao Pai o pão, estamos reconhecendo nossa completa dependência Dele, não só no nível do sustento material, mas também, da necessidade do pão da sua Palavra e da Eucaristia para alimentar nosso espírito, “pois não só de pão vive o homem, mas de toda palavra que sai da boca de Deus” (Mt 4,4). Pedimos o Evangelho, a Palavra de Deus que alimenta nosso viver diário e o pão do Corpo e Sangue de Cristo. Para nós, cristãos, o verdadeiro pão é o próprio Cristo. “Eu sou o pão vivo que desceu do céu. Quem come deste pão viverá eternamente. E o pão que eu darei é minha carne, entregue pela vida do mundo” (Jo 6,51).</p> <p>O pedido de pão adquire uma riqueza extraordinária. Pedimos sustento material e alimento espiritual, tudo o que é necessário para viver.</p> <p><strong>Dinâmica:</strong> Apresentar o vaso de flores para os catequizandos, fazendo uma analogia com o texto bíblico. No texto, vemos que Deus providencia o necessário para que a planta cresça viçosa e com veste necessária. Passar o vaso de mão em mão para os catequizandos contemplarem a criação divina: reparar as cores, formato, textura, se possui perfume...</p> <p>Logo após, mostrar as imagens dos pássaros: são livres, não precisam trabalhar, mas têm o seu alimento garantido e tudo o mais de que necessitam para sua sobrevivência.</p> <p>Refletir junto aos catequizandos:</p> <ul> <li><p>Se Deus se preocupa e cuida tanto assim de uma flor que é tão frágil e de vida breve, de pássaros que vivem a sobrevoar os céus (criaturas de Deus), imaginem o que Ele não tem nos reservado? Nós, que não somos somente criaturas, mas filhos, coerdeiros de todo o seu Reino.</p></li> </ul> <p><strong>Conclusão:</strong> Pedir o pão para o nosso dia a dia nos torna pessoas que esperam da bondade do seu Pai do Céu tudo o que é necessário, tanto os bens materiais como os espirituais. Nenhum cristão deve fazer esse pedido sem pensar também na sua responsabilidade real por aqueles a quem faltam os bens mais básicos deste mundo.</p> <p>Como gesto concreto, sugerimos que os catequizandos sejam motivados a trazer, para o próximo encontro, alimentos não perecíveis, roupas e brinquedos, para serem partilhados com alguma família carente, ou ainda bolo, pão, refrigerante e outros alimentos, para serem levados a um asilo e partilhar o café com os internos. O interessante seria que todos os catequizandos fossem até o local escolhido e ali vissem a realidade dos menos favorecidos, como sugerido no próximo encontro.</p> <p><strong>Oração final:</strong> Ao redor da Mesa da Palavra, o catequista motiva os catequizandos a formularem preces e orações pedindo o pão necessário à nossa sobrevivência, não se esquecendo dos nossos pobres. Poderá encerrar com o Pai-Nosso e com a oração:</p> <blockquote> <p><em>Senhor, nosso Deus, que cuida de cada um de nós com carinho, provendo o alimento necessário para o nosso sustento. Ajuda-nos a partilhar com alegria o que temos. Por Cristo, nosso Senhor. Amém.</em></p> </blockquote> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte dizendo:</p> <blockquote> <p><em>“N..., partilhai com alegria o que tens. Vai em paz e que o Senhor te acompanhe! Amém”.</em></p> </blockquote> <h4>MATERIAL DE APOIO</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 2828 a 2837 do Catecismo da Igreja Católica (CIC).</p></li> </ul> <p><strong>Atenção</strong></p> <p>No próximo encontro, sugerimos uma vivência, onde os catequizandos serão convidados a visitar alguma família carente ou instituição que cuide de pessoas pobres ou abandonadas. Se o catequista optar pela nossa sugestão da visita, explicar neste encontro ainda como será a vivência: como deverão se organizar, o que deverão levar e onde se encontrar. O dia e o horário poderão ser diferentes dos da catequese, favorecendo a participação de todos, bem como a disponibilidade da família ou instituição escolhida. Se for escolhida alguma família para ser visitada, o grupo de catequizandos poderá ser dividido em pequenos grupos, facilitando, na prática, a visita e não constrangendo também a família visitada, que talvez não tenha como acolher e acomodar a todos. Neste caso, várias famílias poderão ser visitadas e depois, no próximo encontro, poderão partilhar como foi fazer a visita e os sentimentos que tiveram. Poderão ser incentivados a, antes, fazer uma pequena coleta de alimentos na comunidade para levar às famílias.</p> <p>Os pais também poderão ser incentivados a participar dessa ação, tanto da coleta como da visita.</p> <p>Antes da visita, sugerimos um breve encontro, onde os catequizandos serão preparados sobre como se portar durante a visita, bem como farão uma pequena oração antes de saírem.</p>', '<p>Ambão com toalha da cor do Tempo Litúrgico, Bíblia, vela e recortes de revistas que mostram pássaros livres e um vaso de flor (preferencialmente lírio).</p>', 18 where not exists (select 1 from encontros where etapa_id=(select id from etapas where numero=3) and ordem=18); -- O pão nosso de cada dia nos dai hoje
insert into encontros (etapa_id, numero, tipo, titulo, tempo_liturgico, leitura_biblica, conteudo_html, preparo_html, ordem) select (select id from etapas where numero=3), 16, 'encontro', 'O pão de cada dia', null, 'At 2,42-47', '<p><strong>Palavra inicial:</strong> Prezado catequista, no encontro de hoje queremos fazer uma vivência, levando os catequizandos a conhecer a realidade de uma família menos favorecida ou de um instituição que cuide de pessoas carentes. Se o catequista optar por não fazer a visita, sugerimos, além da oração inicial, que servirá para os dois momentos, um breve esquema de encontro.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, Bíblia e alimentos a serem partilhados.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os carinhosamente com a frase: “<em>Vamos partilhar com alegria nossos dons, N...!</em>”.</p> <p><strong>Recordação da vida:</strong> Neste momento, ao redor da Mesa da Partilha ou da Mesa da Palavra, recordar fatos e acontecimentos que marcaram a vida da comunidade e como foi fazer a coleta de mantimentos que serão partilhados.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista, reunindo todos os acontecimentos da recordação da vida, inicia a oração, invocando o Espírito Santo.</p> <p>Depois, um catequizando dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> At 2,42-47.</p> <p>Após um momento de silêncio, o catequista lê o texto novamente, bem devagar, destacando alguns pontos.</p> <blockquote> <p><em>“Eles eram perseverantes em ouvir o ensinamento dos apóstolos, na comunhão fraterna, na partilha do pão e nas orações...”.</em></p> </blockquote> <p>Se o catequista optar por não fazer a visita, todos se dirigem para a Mesa da Partilha. Se forem fazer a visita, o catequista encerra o momento de oração e os convida a saírem para a vivência.</p> <h4>Na Mesa da Partilha</h4> <p>O catequista estimula os catequizandos a falarem o que entenderam do texto. Depois, pedir aos catequizandos para abrirem suas Bíblias na passagem proclamada na Mesa da Palavra e convidá-los a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto.</p> <p>O catequista poderá conversar com os catequizandos sobre a realidade e a diferença social vivida em nosso país, comentando as diferenças que separam as pessoas, as razões porque alguns possuem tanto e outros estão sem nada, sem o necessário para viver dignamente. Proporcionar uma reflexão sobre as razões dessas diferenças e o que podemos fazer para diminuir a desigualdade social.</p> <p>Poderá ressaltar a importância de não se desperdiçar comida e lembrar o encontro da primeira etapa, em que aprendemos a rezar antes das refeições agradecendo a Deus pelo alimento que temos em nossa mesa.</p> <p>Outros temas pertinentes poderão ser lembrados pelo catequista, contemplando a realidade dos catequizandos.</p> <p>Se não forem realizadas as visitas, os alimentos arrecadados poderão ser encaminhados à Pastoral Social ou a alguma entidade beneficente.</p> <p><strong>Conclusão:</strong> O catequista conclui dizendo que a partilha não deve ser feita somente uma vez por ano, mas deve ser constante em nossa vida. Os pobres comem durante todo o ano. Poderá ser combinado com os catequizandos para que todo mês se comprometam em trazer algo para ser partilhado e entregue à Pastoral Social ou a alguma família “adotada” pela turma de catequese.</p> <p><strong>Oração final:</strong> O catequista convida os catequizandos a ficarem em pé ao redor da Mesa da Palavra para a oração final, motivando-os a formularem orações e preces. Reza-se a oração do Pai-Nosso e conclui-se com a oração:</p> <blockquote> <p><em>Ó Deus, fonte de toda a vida, queremos, a exemplo do teu Filho, Jesus, e da nossa Igreja, ter um especial olhar pelos mais pobres de nossa sociedade. Queremos verdadeiramente ser cristãos, partilhando com alegria o que temos. Por Cristo, nosso Senhor. Amém.</em></p> </blockquote> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte dizendo:</p> <blockquote> <p><em>“N..., sede perseverante na partilha do pão. Vai em paz e que o Senhor te acompanhe!”.</em></p> </blockquote> <h4>Lembrete</h4> <p>Solicitar a todos que tragam o <em>Diário Catequético e Espiritual do Catequizando</em> no próximo encontro, pois iremos utilizar a carteirinha de dizimista que está no anexo.</p>', '<p>Ambão com toalha da cor do Tempo Litúrgico, vela, Bíblia e alimentos a serem partilhados.</p>', 19 where not exists (select 1 from encontros where etapa_id=(select id from etapas where numero=3) and ordem=19); -- O pão de cada dia
insert into encontros (etapa_id, numero, tipo, titulo, tempo_liturgico, leitura_biblica, conteudo_html, preparo_html, ordem) select (select id from etapas where numero=3), 17, 'encontro', 'Sou responsável por minha igreja, sou dizimista!', null, 'Mc 12,41-44', '<p><strong>Palavra inicial:</strong> Neste encontro, procuraremos despertar em nossos catequizandos a importância de ser dizimista. Refletir que nós, cristãos, somos os responsáveis pela manutenção da Igreja. Que o dízimo não é o que nos sobra, mas uma parte de tudo aquilo que ganhamos de Deus.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, flores e Bíblia. Para a dinâmica: cartaz com a ilustração de uma grande Igreja, contendo em sua fachada o desenho de tijolos. Neles devem estar escritos alguns dos gastos mensais que a paróquia ou comunidade tem: energia, água, hóstias, vinho, salário com funcionários, cursos, formação das lideranças, flores, entre outros; fichas para o cadastro de dizimistas; carteirinha do dizimista (no anexo do <em>Diário</em> de cada catequizando) e etiquetas de preço simbolizando tijolinhos onde será marcada a contribuição do catequizando.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos saudando-os com a frase: “<em>N..., você também é responsável pela manutenção de nossa comunidade!</em>” e os conduz para dentro da sala de encontro.</p> <p><strong>Recordação da vida:</strong> Após serem acolhidos, ao redor da Mesa da Partilha ou da Mesa da Palavra, farão uma retrospectiva da semana, e o catequista poderá perguntar sobre o encontro anterior, pedindo para que conversem sobre o que cada um experienciou. Poderão destacar, ainda, os acontecimentos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista motiva a oração inicial. Invocar o Espírito Santo rezando ou cantando.</p> <p>Depois, um catequizando dirige-se até o ambão, de onde proclama o texto bíblico. Antes, porém, todos poderão cantar, aclamando o Evangelho.</p> <p><strong>Leitura do texto bíblico:</strong> Mc 12,41-44.</p> <p>Depois de um momento de silêncio o catequista lê o texto novamente, bem devagar, destacando alguns pontos.</p> <blockquote> <p><em>“...veio, então, uma pobre viúva e pôs no cofre apenas duas moedinhas [...] Esta pobre viúva deu mais do que todos os que depositaram no cofre [...] ela, porém, na sua indigência, deu tudo que tinha, todo o seu sustento”.</em></p> </blockquote> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>O catequista reconstrói o texto bíblico com os catequizandos. Algumas perguntas poderão ajudar: o que as pessoas estavam fazendo? Quem foi a pessoa que mais ofertou? Por quê? Depois, pedir aos catequizandos para abrirem suas Bíblias na passagem proclamada na Mesa da Palavra, e os convidar a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar.</p> <p>O catequista então começa a refletir com os catequizandos sobre a importância do dízimo para manutenção e sobrevivência da Igreja.</p> <p>Introduz pedindo para que os catequizandos olhem para a sala da catequese e depois se lembrem da Igreja, enfim, de toda a estrutura da paróquia e da comunidade e os questiona dizendo: tudo isso que está aqui hoje, as salas de catequese, a Igreja, as cadeiras, mesas, luz, sala limpa... tudo isso, de onde veio, quem comprou, quem mantém tudo isso?</p> <p>Depois de ouvi-los, o catequista diz que tudo isso é mantido com o dinheiro do dízimo e com ofertas doadas pelos fiéis.</p> <p>Poderá ainda perguntar se já ouviram falar do dízimo e o que ele significa. O catequista, então, explica que o dízimo é a décima parte de tudo aquilo que ganhamos e que deveria ser ofertada à Igreja para a manutenção da comunidade. O dízimo tem origem no Antigo Testamento (Lv 27,30) e era tido como 10% de tudo o que era produzido. O versículo do texto bíblico poderá ser lido com os catequizandos.</p> <p>O catequista, então, esclarece a importância de todos os fiéis batizados terem a consciência de que são responsáveis por manter a Igreja e seu projeto de evangelização. Depois, abre o cartaz com o desenho da igreja e mostra quais são os principais gastos, apontando os tijolos nela desenhados. Diz que o dinheiro arrecadado no dízimo, além de manter os gastos com a estrutura (luz, água...), é também revertido para a evangelização (formação de agentes de pastoral, missões...), bem como destinado às obras de caridade (hospitais, creches, orfanatos, asilos mantidos pela Igreja, além de ser enviado para regiões e países mais pobres). Estas são as três dimensões do dízimo: religiosa, missionária e social.</p> <p>O catequista poderá perguntar se algum catequizando já é dizimista ou se sabe se os pais contribuem com o dízimo.</p> <p>Propor que todos os catequizandos sejam dizimistas, dizendo que poderiam comprometer-se dando uma parte daquilo que ganham dos pais, avós e de outras pessoas. Sugerir para que todos os meses deixem de comprar algo de que gostam para oferecer como seu dízimo, sua parcela de contribuição na manutenção e sustento da Igreja e das obras de evangelização e caridade. Ouvir o que os catequizandos acham e como poderiam ser dizimistas, o que poderiam deixar de comprar para poder devolver como dízimo, lembrando a passagem do Evangelho que foi lida. A viúva deu tudo o que tinha para sobreviver. E nós, o que podemos dar? Aquilo que nos sobra ou aquilo que vai nos faltar?</p> <p><strong>Atividade:</strong> O catequista distribui uma ficha de cadastro de dizimista para cada catequizando e diz que deverá ser preenchida e entregue na mesa do dízimo na Igreja ou na secretaria paroquial, e que a partir do momento em que a ficha for entregue, eles se tornarão dizimistas. É importante que seja a mesma ficha que é preenchida pelos adultos e que seja entregue onde a comunidade costuma devolver o seu dízimo, pois é uma maneira de criar vínculo entre a Pastoral do Dízimo e os catequizandos. O catequista não pode se esquecer de conversar com o padre e com os agentes da Pastoral do Dízimo, para buscar formar essa pastoral de conjunto.</p> <ul> <li><p>Depois, o catequista pedirá a cada um que abra o seu <em>Diário</em> e recorte a carteirinha de dizimista. Orientar que todos os meses o catequizando deverá levar a carteirinha e o seu dízimo até a Igreja ou mesa do dízimo e ali fazer a entrega da sua oferta. Mostrar a etiqueta e dizer que todas as vezes que o dízimo for devolvido, será colado aquele adesivo com o valor da contribuição.</p></li> </ul> <ul> <li><p>Na mesa do dízimo e/ou na secretaria da Pastoral do Dízimo deverá ter a etiqueta para ser colada na carteirinha do catequizando com o valor entregue, lembrando que o nosso dízimo é um tijolinho, ou seja, a nossa contribuição para a construção da Igreja de Cristo.</p></li> </ul> <p><strong>Conclusão:</strong> Desde o dia em que fomos batizados, passamos a fazer parte desta grande família, que é a Igreja Católica Apostólica Romana. Desde então, assumimos também a responsabilidade pela sua manutenção e obras de evangelização. Com o nosso gesto concreto, ser dizimistas, queremos nos comprometer cada vez mais com o anúncio do Evangelho.</p> <p>Pedir para que durante a semana os catequizandos conversem com seus pais ou responsáveis sobre a importância de ser dizimista.</p> <p><strong>Oração final:</strong> O catequista convida os catequizandos a ficarem em pé ao redor da Mesa da Palavra. Depois, quando todos estiverem em silêncio, convidá-los a formular preces, pedindo pela Igreja, pelos missionários e por todos os dizimistas, além dos pedidos particulares que cada um traz no coração. Depois, prosseguindo as preces, convidá-los a rezarem juntos o Pai-Nosso e concluir com a oração:</p> <blockquote> <p><em>Ó, Pai bondoso, mais uma vez aqui nos reunimos em teu nome. Queremos verdadeiramente assumir nossa responsabilidade na manutenção da tua Igreja. Dá-nos coragem e espírito de desprendimento, para partilharmos o pouco que temos. Por Cristo, nosso Senhor. Amém.</em></p> </blockquote> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte dizendo:</p> <blockquote> <p><em>“N..., responsável pela Igreja de Cristo, vai em paz e que o Senhor te acompanhe!”.</em></p> </blockquote> <h4>Lembrete</h4> <p>O próximo encontro será a “celebração do pão”. Enviar convite aos pais e à comunidade. Combinar, se achar conveniente, uma pequena confraternização ao final, partilhando bolos e refrigerante.</p>', '<p>Ambão com toalha da cor do Tempo Litúrgico, vela, flores e Bíblia. Para a dinâmica: cartaz com a ilustração de uma grande Igreja, contendo em sua fachada o desenho de tijolos. Neles devem estar escritos alguns dos gastos mensais que a paróquia ou comunidade tem: energia, água, hóstias, vinho, salário com funcionários, cursos, formação das lideranças, flores, entre outros; fichas para o cadastro de dizimistas; carteirinha do dizimista (no anexo do Diário de cada catequizando) e etiquetas de preço simbolizando tijolinhos onde será marcada a contribuição do catequizando.</p>', 20 where not exists (select 1 from encontros where etapa_id=(select id from etapas where numero=3) and ordem=20); -- Sou responsável por minha igreja, sou dizimista!
insert into encontros (etapa_id, numero, tipo, titulo, tempo_liturgico, leitura_biblica, conteudo_html, preparo_html, ordem) select (select id from etapas where numero=3), 18, 'celebracao', 'Celebração do Pão', null, null, '<p>(É importante convidar toda a comunidade, os pais e padrinhos de Batismo de cada catequizando para a celebração.)</p> <p><strong>Palavra inicial:</strong> Esta celebração tem como objetivo aprofundar o sentido do pão como alimento do ser humano, sinal de comunhão e partilha. Deseja-se ainda promover uma integração entre catequese e comunidade.⁶</p> <p><strong>Preparando o ambiente:</strong> No centro do espaço celebrativo, uma grande toalha estendida no chão ou sobre algumas pilastras ou colunas de diversos tamanhos. Pães de vários tipos (pão de sal – francês –, pão doce, mini pão, pão de milho, pão duro, pão ázimo) e um grande pão que deverá ser partilhado no final (este deverá ficar no centro do espaço celebrativo).</p> <p><strong>Distribuindo funções:</strong> Seria importante também dividir algumas funções com antecedência:</p> <ul> <li><p>animador: para orientar as pessoas durante a celebração;</p></li> <li><p>catequizandos para entrar com os pães;</p></li> <li><p>presidente: de preferência o próprio catequista;</p></li> <li><p>pessoa para proclamar a leitura bíblica;</p></li> <li><p>pessoa para cantar o salmo;</p></li> <li><p>pessoa para fazer a Oração da Assembleia;</p></li> <li><p>cantores (<em>deverão escolher com antecedência os cantos</em>);</p></li> <li><p>ministros para acolhida (os próprios catequistas ou membros da comunidade).</p></li> </ul> <p>Conforme os fiéis chegam e adentram o local da celebração, pode-se cantar um refrão meditativo. Quando todos já se encontrarem acomodados, o animador acolhe calorosamente a todos e os convida a ficarem de pé para iniciar a celebração com um canto.</p> <p><strong>Saudação inicial</strong></p> <p><strong>Presidente:</strong> <em>Em nome do Pai e do Filho e do Espírito Santo. Amém.</em></p> <p><em>Que a graça e a Paz de nosso Deus Criador, de Jesus Cristo, nosso Senhor, e do Espírito Santo, nosso santificador, estejam convosco.</em></p> <p><strong>R:</strong> <em>Bendito seja Deus que nos reuniu no amor de Cristo.</em></p> <p><strong>Presidente:</strong> <em>Queridos catequizandos, pais, padrinhos e comunidade, com esta celebração queremos refletir sobre o pão, alimento presente em tantas culturas e escolhido pelo próprio Jesus, para que seja sinal de sua presença em meio aos homens. Com esta celebração, queremos ainda meditar sobre o alimento que partilhamos em família e com os mais necessitados. Enfim, falar de pão é falar de trabalho, vida digna e fé. Façamos nosso momento de recordação da vida.</em></p> <p><strong>Recordação da vida:</strong> Alguns catequizandos entram trazendo os diversos tipos de pães e colocando sobre a toalha ou colunas previamente preparadas. Enquanto cada tipo de pão entra, um leitor lê o texto:</p> <p><strong>Pão de sal (francês):</strong> <em>Recordamos, com este pão, todos os trabalhadores que lutam para dar vida digna às suas famílias.</em></p> <p><strong>Pão doce:</strong> <em>Lembramos a doçura e o encanto da mulher. Recordamos, com este pão doce, todas as mulheres de nossa Igreja, que dão a vida pela nossa comunidade, sendo sinal de vida e doação.</em></p> <p>⁶ Celebração adaptada da proposta de Vanildo Paiva, no livro: PAIVA, Vanildo. Catequese e Liturgia. Duas faces do mesmo mistério. 2. ed. São Paulo: Paulus, 2008.</p> <p><strong>Mini pão:</strong> <em>O mini pão nos faz lembrar das inúmeras famílias que vivem apenas com um salário mínimo, além de nos recordar as inúmeras pessoas desempregadas.</em></p> <p><strong>Pão de milho:</strong> <em>Recordamos, com o pão de milho, o trabalhador rural e a mulher do campo, que batalham de sol a sol para que não falte o pão de cada dia em nossas casas.</em></p> <p><strong>Pão duro:</strong> <em>Apresentamos o pão duro, sinal das pessoas que não sabem partilhar, que vivem isolados em seu egoísmo, não sabendo dividir o pão, as roupas, os brinquedos...</em></p> <p><strong>Prato sem pão:</strong> <em>Recordamos também aqueles que nada têm em seus pratos. Aqueles que passam fome, frio, não têm remédios nem casa parar morar.</em></p> <p><strong>Pão ázimo:</strong> <em>O pão escolhido por Jesus como sinal de sua presença no meio de nós. O pão ázimo torna-se, na Santa Missa, o Corpo de Cristo, dado em alimento a cada um de nós.</em></p> <p><strong>Momento penitencial:</strong> <em>Diante de tantos tipos de pão, reflexo de nossa sociedade que trabalha e luta por um mundo melhor, com mais vida e dignidade, humildemente peçamos perdão a Deus por todas as vezes que não soubemos partilhar o pão de cada dia com nossos irmãos e irmãs:</em></p> <p><em>– Pelas vezes que não partilhamos o pão com os mais necessitados.</em></p> <p><strong>R.:</strong> <em>Perdão, Senhor, tende piedade de nós (ou cantando).</em></p> <p><em>– Pelas vezes que esbanjamos os alimentos, desperdiçando comida.</em></p> <p><strong>R.</strong></p> <p><em>– Pelas vezes que exploramos os trabalhadores, não pagando salários dignos.</em></p> <p><strong>R.</strong></p> <p><em>– Pelas vezes que julgamos nossos irmãos e irmãs.</em></p> <p><strong>R.</strong></p> <p><em>– Pelas vezes que não nos aproximamos da santa Eucaristia com o coração puro.</em></p> <p><strong>R.</strong></p> <p><em>– Pelas vezes que não testemunhamos Jesus Cristo e não fomos exemplo de Cristão.</em></p> <p><strong>R.</strong></p> <p><strong>Presidente:</strong> <em>Deus, todo-poderoso tenha compaixão de nós, perdoe os nossos pecados e nos conduza à vida eterna. Amém.</em></p> <p><strong>Presidente:</strong> <em>Oremos. Deus, Pai de bondade, que vos dignastes enviar vosso Filho como alimento a cada um de nós, ensinai-nos a sempre partilhar o pão de cada dia, para que este não falte na mesa dos nossos irmãos e irmãs. Amém.</em></p> <p><em>Podemos nos assentar para ouvir o que Deus tem a nos falar.</em></p> <p><strong>1ª Leitura:</strong> Atos 4,32-37.</p> <p><strong>Salmo (104/103):</strong> “<em>Hino de louvor ao Deus que nos liberta e nos dá o pão de cada dia</em>”.</p> <p><strong>R.:</strong> <em>Louvado seja o meu Senhor! Louvado seja o meu Senhor!</em></p> <p><em>Senhor, meu Deus, como és tão grande! Eu canto teu louvor, com alegria. Água boa tu derramas pelos campos, e dela bebem os animais todos os dias.</em></p> <p><strong>R.</strong></p> <p><em>E o homem tira dos campos o seu pão, seu coração fica feliz com o bom vinho. O alimento traz a força e a coragem. Obrigado! Tu nos tratas com carinho.</em></p> <p><strong>R.</strong></p> <p><em>Todos esperam de ti o alimento que, generoso, dás a todos com fartura. Abre tua mão e felizes ficaremos! Em ti, Senhor, espera toda criatura!</em></p> <p><strong>R.</strong></p> <p><em>Por toda vida ao Senhor eu vou cantar, por toda vida ao meu Deus, o meu louvor! Que o meu canto lhe seja sempre agradável, pois minh’alegria se encontra no Senhor!</em></p> <p><strong>R.</strong></p> <p><strong>Aclamação ao Evangelho</strong></p> <p>Eu vim para escutar tua Palavra, tua Palavra, tua Palavra de amor!</p> <p><strong>Evangelho:</strong> Mc 14,12-16.22-26.</p> <p><strong>Reflexão:</strong> Em poucas palavras, mostrar o valor da Eucaristia, centro da nossa fé e alimento para nossa vida. Jesus se utiliza deste alimento tão comum de sua época para nos comunicar seu amor. Ele se dá em alimento sobre as espécies do Pão e do Vinho. O pão ázimo, feito de farinha de trigo e água, consagrado torna-se o Corpo de Cristo. Comungar o Pão Eucarístico é comungar o projeto de vida e de partilha instaurado por Jesus.</p> <p>Porém, de nada adianta comungar do Corpo de Cristo se eu não O enxergo em meu irmão. O pão de cada dia é alimento do ser humano, fruto do trabalho, do esforço e da luta cotidiana; sinal de unidade e da comunhão entre as pessoas. Comungar do Cristo é partilhar nossos dons, é formar comunidade, é ser um só corpo. Sendo assim, é preciso partilhar, pois muitos não têm o pão e a dignidade necessários.</p> <p>Jesus escolheu o pão para permanecer entre nós e nos alimentar com seu amor.</p> <p>Logo após a reflexão, o presidente convida a todos a meditarem alguns instantes em silêncio. Depois, convida-os a ficarem de pé e elevarem a Deus preces e louvores.</p> <h4>Preces</h4> <p><strong>Presidente:</strong> <em>Elevemos a Deus nossos louvores e pedidos comunitários:</em></p> <p><strong>R:</strong> <em>Louvado seja nosso Deus, pelo pão da vida!</em></p> <p><em>- Senhor, nós te louvamos pelo pão que colocaste em nossa mesa a cada dia.</em></p> <p><strong>R.</strong></p> <p><em>– Senhor, nós te louvamos pelo pão do seu corpo, alimento para nossa Salvação.</em></p> <p><strong>R.</strong></p> <p><em>– Senhor, nós te louvamos pela nossa comunidade que partilha com alegria seus dons.</em></p> <p><strong>R.</strong></p> <p><em>– Senhor, dá-nos a coragem de não cruzar os braços diante de tanta desigualdade social.</em></p> <p><strong>R.</strong></p> <p><em>– Senhor, ensinai-nos a não desperdiçar e a dividir com alegria o pão de cada dia.</em></p> <p><strong>R.</strong></p> <p>(Outras preces e pedidos espontâneos.)</p> <p><strong>Presidente:</strong> <em>Prossigamos nossas preces rezando a oração que o Senhor nos ensinou. Pai nosso...</em></p> <p><strong>Partilha:</strong> O presidente pega o pão grande no centro do espaço celebrativo e o parte ao meio. Entrega uma parte a um ministro ou catequista e, enquanto todos cantam, distribui-se um pedaço do pão a cada participante, pedindo que estes o segurem. Quando todos tiverem recebido o pão, o presidente da celebração convida a todos a erguerem o pedaço de pão e a repetirem a oração:</p> <blockquote> <p><em>Senhor, Deus da vida, tu que nos sustentas com o alimento da terra e com o Pão que vem do Céu, permite que jamais nos falte o pão de cada dia e que saibamos sempre repartir com aqueles que nada têm. Amém!</em></p> </blockquote> <p>(Em seguida, comem o pão em silêncio e o presidente conclui a celebração.)</p> <p><strong>Bênção final:</strong> <em>Que o Deus, que a todos alimenta com amor e carinho, esteja sempre convosco. Amém!</em></p> <p><em>Deus, nosso Pai criador, sempre nos abençoe e nos guarde! Amém!</em></p> <p><em>Louvado seja nosso Senhor, Jesus Cristo!</em></p> <p><strong>R:</strong> <em>Para sempre seja louvado!</em></p> <p><strong>Lembrete:</strong> É importante que esta celebração aconteça no dia em que a comunidade costuma se reunir para rezar, facilitando assim a sua participação.</p> <p><strong>Confraternização e partilha:</strong> Ao final da celebração, poderá ser realizada uma pequena confraternização ou partilha, onde cada participante trará um prato de bolo, doce ou salgado, ou ainda refrigerante ou suco, e todos partilharão uns com os outros, promovendo um espaço de integração, diálogo e convivência.</p>', '<p>No centro do espaço celebrativo, uma grande toalha estendida no chão ou sobre algumas pilastras ou colunas de diversos tamanhos. Pães de vários tipos (pão de sal – francês –, pão doce, mini pão, pão de milho, pão duro, pão ázimo) e um grande pão que deverá ser partilhado no final (este deverá ficar no centro do espaço celebrativo).</p>', 21 where not exists (select 1 from encontros where etapa_id=(select id from etapas where numero=3) and ordem=21); -- Celebração do Pão
insert into encontros (etapa_id, numero, tipo, titulo, tempo_liturgico, leitura_biblica, conteudo_html, preparo_html, ordem) select (select id from etapas where numero=3), 19, 'encontro', 'Perdoai-nos as nossas ofensas', null, 'Mc 11,24-25', '<p><strong>Palavra inicial:</strong> Amados catequistas, no encontro de hoje queremos refletir com os catequizandos o pedido ao Pai para que perdoe nossas ofensas, ou seja, que nos perdoe por não respondermos ao seu amor, por não vivermos os seus mandamentos. De modo especial, queremos meditar sobre os dez mandamentos.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela e flores. Cartaz grande com os dez mandamentos escritos e outro cartaz apenas com a numeração de 1 a 10. Tiras de papel com cada mandamento escrito separadamente, sem o número que identifique a sua ordem. Folha impressa com os dez mandamentos para ser entregue a cada catequizando.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos saudando-os com a frase: “<em>Deus sempre nos perdoa, N... Seja bem-vindo!</em>” e os conduz para dentro da sala. Quando já estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas.</p> <p><strong>Recordação da vida:</strong> Ao redor da Mesa da Partilha ou da Mesa da Palavra, o catequista motiva os catequizandos a fazerem um momento de recordação da vida, destacando fatos e acontecimentos que marcaram a vida da comunidade. Poderão partilhar como foi a participação na “celebração do pão” e o que aprenderam com ela.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Após a recordação da vida, o catequista inicia a oração, de maneira bem espontânea, invocando o Espírito Santo rezando ou cantando.</p> <p>Ainda em clima de oração, o catequista convida a todos a aclamarem o Evangelho. O catequizando dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> Mc 11,24-25.</p> <p>Depois de um momento de silêncio, o catequista lê o texto novamente, bem devagar, destacando alguns pontos.</p> <blockquote> <p><em>“...perdoai, se por acaso tiverdes alguma coisa contra alguém, para que também vosso Pai que está no céu vos perdoe os pecados”.</em></p> </blockquote> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Ao redor da Mesa da Partilha, os catequizandos reconstroem o texto bíblico. Depois, pedir aos catequizandos para abrirem suas Bíblias na passagem proclamada na Mesa da Palavra e convidá-los a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar.</p> <p>O catequista, então, conversa com os catequizandos dizendo que na Bíblia o pecado pode ser entendido de diversas formas: rebeldia contra Deus, desviar de seus caminhos e se afastar de sua presença, desobediência, infidelidade à sua aliança, recusa do seu amor. Na oração do Pai-Nosso, porém, considera-se pecado como uma “dívida”, um vazio, uma falta de resposta ao dom imenso de Deus. O grande pecado da humanidade é a falta de resposta ao seu amor de Pai. Estamos em dívida com Deus.</p> <p>Para Jesus o verdadeiro pecado é a omissão. No último dia seremos julgados não pelo mal que tenhamos praticado, mas pelo que deixamos de fazer aos famintos, pobres, enfermos, estrangeiros, encarcerados, abandonados e excluídos. “Em verdade, vos digo todas as vezes que não fizestes isso a um desses pequeninos, foi a mim que o deixastes de fazer” (Mt 25,45).</p> <p>O pecado, portanto, não é só transgressão a uma lei, é muito mais, é deixar de responder ao projeto de amor e salvação que Deus tem para cada um de nós. É uma ofensa pessoal a um Pai do qual tudo recebemos e que espera que nos amemos como verdadeiros irmãos.</p> <p>Nosso pedido de perdão só é possível se reconhecemos nosso pecado e nossa dívida. Todos somos pecadores, e Deus conhece o coração de cada um de nós e nos perdoa sempre. Porém, é preciso que olhemos para dentro de nós, que nos examinemo-nos e reconheçamos que somos pecadores. Assim como os doentes são os que precisam de médico, os pecadores são os que precisam de Deus.</p> <p>Quando reconhecemos ser pecadores, quando nos arrependemos, nasce em nós um pedido, uma súplica: perdoa-nos. O arrependimento é fundamental para que esse pedido seja sincero e de coração. É preciso reconhecer que somos pequenos, fracos e pecadores.</p> <p>Deus nos dá os mandamentos e as leis. Não para oprimir o homem, mas para ajudá-lo a viver em plenitude. As leis são para o bem do ser humano.</p> <p>Deus dá a Moisés, no alto da montanha, dez mandamentos que, ao serem cumpridos, nos darão felicidade e vida longa ao ser humano.</p> <p>O catequista poderá perguntar aos catequizandos se eles sabem quais são estes mandamentos. Deixar que falem.</p> <p>Depois, apresentar o primeiro cartaz com os dez mandamentos impressos.</p> <blockquote> <p><em>1º Amar a Deus sobre todas as coisas.</em><br/> <em>2º Não tomar seu santo nome em vão.</em><br/> <em>3º Guardar domingos e festas de guarda.</em><br/> <em>4º Honrar pai e mãe.</em><br/> <em>5º Não matar.</em><br/> <em>6º Não pecar contra a castidade.</em><br/> <em>7º Não furtar.</em><br/> <em>8º Não levantar falso testemunho.</em><br/> <em>9º Não desejar a mulher do próximo.</em><br/> <em>10º Não cobiçar as coisas alheias.</em></p> </blockquote> <p>O catequista, então, poderá explicar brevemente cada um dos mandamentos (aprofundar estudo nos números 2052 a 2557 do <em>Catecismo da Igreja Católica</em>).</p> <p><strong>Dinâmica:</strong> O catequista poderá espalhar na mesa, de cabeça para baixo, tiras com cada um dos dez mandamentos escritos separadamente. Pedir para que dez catequizandos peguem um papel cada um. Depois, disponibilizar o cartaz apenas com os números de 1 a 10 e pedir para que cada catequizando, com a ajuda dos demais colegas, cole o mandamento equivalente ao número, colocando-os, assim, na ordem. Depois de colarem, o catequista poderá distribuir impresso em uma pequena folha os dez mandamentos, para que estes colem no seu <em>Diário</em> e os meditem para colocarem em prática.</p> <p><strong>Conclusão:</strong> O catequista conclui dizendo que é preciso responder ao amor de Deus e ao seu projeto de salvação, vivendo os mandamentos e amando os nossos irmãos. O próprio Jesus resumiu os dez mandamentos: amar a Deus sobre todas as coisas e ao próximo como a si mesmo. Não basta amar a Deus se não amamos o nosso irmão.</p> <p>Poderá motivá-los para um canto penitencial, onde todos poderão pensar nos seus erros e reconhecer que são pecadores e precisam da misericórdia de Deus.</p> <p><strong>Oração final:</strong> Ao redor da Mesa da Palavra, o catequista motiva os catequizandos a formularem orações e preces a Deus Pai. Depois, o catequista os convida a concluir com o Pai-Nosso e com a oração:</p> <blockquote> <p><em>Deus de bondade, que conhece o coração de cada um de nós, ajuda-nos a amar o nosso irmão, respeitando e aceitando suas limitações. Que saibamos responder SIM ao teu projeto de amor. Por Cristo, nosso Senhor. Amém</em></p> </blockquote> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte dizendo:</p> <blockquote> <p><em>“Deus conhece nosso coração, N..., e nos perdoa. Vai em paz e que o Senhor te acompanhe!”.</em></p> </blockquote> <h4>MATERIAL DE APOIO</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 2838 a 2841 do <em>Catecismo da Igreja Católica</em> (CIC).</p></li> </ul>', '<p>Ambão com toalha da cor do Tempo Litúrgico, vela e flores. Cartaz grande com os dez mandamentos escritos e outro cartaz apenas com a numeração de 1 a 10. Tiras de papel com cada mandamento escrito separadamente, sem o número que identifique a sua ordem. Folha impressa com os dez mandamentos para ser entregue a cada catequizando.</p>', 22 where not exists (select 1 from encontros where etapa_id=(select id from etapas where numero=3) and ordem=22); -- Perdoai-nos as nossas ofensas
